function DemoButton() {
  const handleClick = (params: any) => {
    console.log('\u6309\u94AE\u70B9\u51FB:', params);
  };

  const handleReset = () => {
    console.log('\u6309\u94AE\u91CD\u7F6E');
  };

  useExpose({
    componentName: 'DemoButton',
    displayName: '\u6F14\u793A\u6309\u94AE',
    category: '\u4EA4\u4E92\u7EC4\u4EF6',
    description: '\u6F14\u793A\u7528\u7684\u6309\u94AE\u7EC4\u4EF6',
    methods: {
      onClick: {
        handler: handleClick,
        description: '\u6309\u94AE\u70B9\u51FB\u4E8B\u4EF6',
        params: {
          event: '\u70B9\u51FB\u4E8B\u4EF6\u5BF9\u8C61',
        },
      },
      onReset: {
        handler: handleReset,
        description: '\u6309\u94AE\u91CD\u7F6E\u4E8B\u4EF6',
      },
    },
  });

  return <button onClick={() => handleClick({})}>\u70B9\u51FB\u6211</button>;
}
